package techguns.gametest;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.blocks.*;
import techguns.items.DecorBlockItem;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class DecorationsGameTests {
    @GameTest(template="empty") public static void allFlattenedDecorativeVariantsRetainCamoAndStackData(GameTestHelper h){h.assertTrue(TGDecorations.ITEMS.size()==127,"All forty-eight source decorative variants and the seventy-nine community edition blocks are registered");for(var entry:TGDecorations.ITEMS.entrySet()){if(!(entry.getValue().get() instanceof DecorBlockItem item))continue;var stack=item.getDefaultInstance().copyWithCount(17);stack.getOrCreateTag().putString("testOwner","preserved");var next=item.cycleStack(stack,false);var restored=((DecorBlockItem)next.getItem()).cycleStack(next,true);h.assertTrue(restored.is(item)&&restored.getCount()==17&&restored.getTag().getString("testOwner").equals("preserved"),"Forward and reverse variant swaps retain count and all custom NBT");}h.succeed();}
    @GameTest(template="empty") public static void camouflageBenchChangesRealBlockVariant(GameTestHelper h){h.setBlock(2,1,2,TGBenches.BLOCKS.get(BenchKind.CAMO).get());var bench=(BenchEntity)h.getBlockEntity(new BlockPos(2,1,2));var player=h.makeMockPlayer();player.setPos(Vec3.atCenterOf(bench.getBlockPos()));bench.inventory.setStackInSlot(0,TGDecorations.ITEMS.get("container_red").get().getDefaultInstance().copyWithCount(8));var menu=new BenchMenu(1,player.getInventory(),bench);menu.clickMenuButton(player,2);h.assertTrue(bench.inventory.getStackInSlot(0).is(TGDecorations.ITEMS.get("container_green").get())&&bench.inventory.getStackInSlot(0).getCount()==8,"Camo bench replaces the flattened item rather than writing an unused metadata tag");menu.clickMenuButton(player,3);h.assertTrue(bench.inventory.getStackInSlot(0).is(TGDecorations.ITEMS.get("container_red").get()),"Reverse button returns to the original block");h.succeed();}
    @GameTest(template="empty") public static void netsConnectAcrossCamouflageButKeepSeparateTopAndWallMeshes(GameTestHelper h){var wall=(DecorNetBlock)TGDecorations.BLOCKS.get("camonet_wood").get();h.setBlock(2,1,2,wall);h.setBlock(3,1,2,TGDecorations.BLOCKS.get("camonet_desert").get());h.setBlock(2,1,1,TGDecorations.BLOCKS.get("camonet_top_wood").get());var pos=h.absolutePos(new BlockPos(2,1,2));h.assertTrue(wall.connections(h.getLevel(),pos)==4,"Different wall camos connect, top panels do not join vertical net arms");var shape=wall.getCollisionShape(h.getLevel().getBlockState(pos),h.getLevel(),pos,net.minecraft.world.phys.shapes.CollisionContext.empty());h.assertTrue(Math.abs(shape.bounds().maxX-1)<.001&&Math.abs(shape.bounds().minZ-7/16d)<.001,"Vertical collision is the source thin post with one connected arm");var top=(DecorNetBlock)TGDecorations.BLOCKS.get("camonet_top_wood").get();var topPos=h.absolutePos(new BlockPos(2,1,1));h.assertTrue(Math.abs(top.getShape(h.getLevel().getBlockState(topPos),h.getLevel(),topPos,net.minecraft.world.phys.shapes.CollisionContext.empty()).bounds().maxY-1/16d)<.001,"Top net keeps its one-pixel thickness");h.succeed();}
    @GameTest(template="empty") public static void lampsEmitLightAndDropWhenSupportIsRemoved(GameTestHelper h){var lamp=(DecorLampBlock)TGDecorations.BLOCKS.get("lamp_yellow").get();h.setBlock(2,1,2,Blocks.STONE);h.setBlock(2,2,2,lamp.defaultBlockState().setValue(DecorLampBlock.FACING,Direction.DOWN));h.assertTrue(h.getBlockState(new BlockPos(2,2,2)).getLightEmission()==15,"Source lamps emit full block light");h.setBlock(2,1,2,Blocks.AIR);h.assertTrue(h.getBlockState(new BlockPos(2,2,2)).isAir(),"A lamp cannot float after its backing block is removed");h.succeed();}
    @GameTest(template="empty") public static void sandbagsUseOneBlockHeightRatherThanFenceCollision(GameTestHelper h){var block=(DecorSandbagsBlock)TGDecorations.BLOCKS.get("sandbags").get();h.setBlock(2,1,2,block);h.setBlock(2,1,1,block);var pos=h.absolutePos(new BlockPos(2,1,2));var bounds=block.getCollisionShape(h.getLevel().getBlockState(pos),h.getLevel(),pos,net.minecraft.world.phys.shapes.CollisionContext.empty()).bounds();h.assertTrue(bounds.maxY==1&&bounds.minZ==0&&bounds.minX==.25&&bounds.maxX==.75,"Sandbags connect as source arms with full block height and half-block width");h.succeed();}
}
